package com.logatron.audit.web;
import com.logatron.audit.application.AuditService;import com.logatron.auth.application.AuthorizationService;import jakarta.servlet.http.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.stereotype.Component;import org.springframework.web.servlet.HandlerInterceptor;
@Component public class AdministrativeDenialAuditInterceptor implements HandlerInterceptor{private final AuthorizationService authorization;private final AuditService audit;public AdministrativeDenialAuditInterceptor(AuthorizationService authorization,AuditService audit){this.authorization=authorization;this.audit=audit;}@Override public void afterCompletion(HttpServletRequest request,HttpServletResponse response,Object handler,Exception ex){if((response.getStatus()==403||response.getStatus()==404)&&request.getRequestURI().startsWith("/api/v1/admin")){var authentication=SecurityContextHolder.getContext().getAuthentication();if(authentication!=null&&authentication.getPrincipal() instanceof Jwt jwt){try{var actor=authorization.authenticatedUser(jwt);audit.record(actor,"ADMINISTRATION_ACCESS","ADMIN_RESOURCE",null,null,null,"DENIED",request);}catch(RuntimeException ignored){/* Unknown identities are not persisted as trusted actors. */}}}}}
